    '　': 0x00,

    // Hiragana
    'あ': 0x01, 'い': 0x02, 'う': 0x03, 'え': 0x04, 'お': 0x05,
    'か': 0x06, 'き': 0x07, 'く': 0x08, 'け': 0x09, 'こ': 0x0A,
